// ============================================================
// ENDPOINT: [POST] Cadastrar Novo Usuário com Sucesso
// Objetivo: criar um usuário novo e guardar os dados dele
// para os próximos testes (login, consulta) usarem.
// ============================================================

// --- PREPARAÇÃO: guardar o e-mail que enviamos ---
// Lê o "pacote" (Body) que mandamos para a API e transforma em objeto JavaScript
const requestBody = JSON.parse(pm.request.body.raw);

// Guarda o e-mail gerado (com $timestamp) numa variável do Environment.
// Analogia: anotar o nome do convidado na lista, para a portaria (login) conferir depois.
pm.environment.set("email_dinamico", requestBody.email);

// Lê a resposta que a API devolveu e transforma em objeto JavaScript
const jsonData = pm.response.json();

// --- TESTE 1: o usuário foi criado? ---
// 201 = "Created" (criado). É o código padrão quando algo novo é salvo com sucesso.
pm.test("Status code é 201 - Usuário criado e salvo com sucesso", function () {
    pm.response.to.have.status(201);
});

// --- TESTE 2: o e-mail salvo é o mesmo que enviamos? ---
// Antes só conferia se EXISTIA um campo e-mail.
// Agora confere se é EXATAMENTE o e-mail que mandamos (mais rigoroso).
pm.test("O banco de dados persistiu e retornou o e-mail correto", function () {
    pm.expect(jsonData.data.email).to.eql(requestBody.email);
});

// --- GUARDAR O ID PARA OS PRÓXIMOS TESTES ---
// O banco gera um número de identificação (id) para o novo usuário.
// Guardamos em "userId" para o endpoint "Consultar Usuário" buscar exatamente esse usuário.
pm.environment.set("userId", jsonData.data.id);

// ============================================================
// ENDPOINT: [POST] Realizar Login com Sucesso
// Objetivo: entrar com o usuário criado no Endpoint 1 e
// guardar o token (a "pulseira") para os próximos endpoints.
// ============================================================

// Lê a resposta da API e transforma em objeto JavaScript
const response = pm.response.json();

// --- TESTE 1: o login foi aceito? ---
// 200 = "OK". O servidor conferiu e-mail e senha e aprovou.
pm.test("Status code é 200 - Login realizado", function () {
    pm.response.to.have.status(200);
});

// --- TESTE 2: o token (pulseira) veio na resposta? ---
// Antes, se o token não viesse, nada acontecia e o teste "passava".
// Agora, se faltar o token, o teste FALHA e avisa na hora.
pm.test("A resposta contém o token JWT", function () {
    pm.expect(response.authentication.token).to.be.a("string").and.not.be.empty;
});

// --- GUARDAR O TOKEN PARA OS PRÓXIMOS ENDPOINTS ---
// Salva a pulseira em "bearer_token". Os endpoints "Consultar" e "Listar"
// usam essa variável na aba Authorization.
pm.environment.set("bearer_token", response.authentication.token);

// ============================================================
// ENDPOINT: [GET] Consultar Usuário Cadastrado
// Objetivo: buscar pelo id o usuário criado no Endpoint 1,
// usando o token do Endpoint 2, e conferir os dados.
// ============================================================

// Lê a resposta da API e transforma em objeto JavaScript
const jsonData = pm.response.json();

// --- TESTE 1: a busca funcionou? ---
// 200 = "OK". Encontrou o usuário e o token foi aceito.
pm.test("Status code é 200 - Usuário encontrado", function () {
    pm.response.to.have.status(200);
});

// --- TESTE 2: é o usuário certo? ---
// Confere se o e-mail que voltou é o mesmo que cadastramos no Endpoint 1
pm.test("O e-mail retornado confere com o cadastrado", function () {
    pm.expect(jsonData.data.email).to.eql(pm.environment.get("email_dinamico"));
});

// --- TESTE 3 (SEGURANÇA): a senha NÃO pode vir na resposta ---
// Boa prática: a API nunca deve devolver a senha, nem criptografada.
pm.test("Segurança: a resposta não expõe a senha do usuário", function () {
    pm.expect(jsonData.data).to.not.have.property("password");
});

// ============================================================
// ENDPOINT: [GET] Listar Todos os Usuários (Com Token)
// Objetivo: buscar a lista de usuários e conferir se o
// usuário criado no Endpoint 1 está nela.
// ============================================================

// 🧱 PEÇA 1 (LER): guarda a resposta numa caixinha
const jsonData = pm.response.json();

// 🧱 PEÇA 5 (PEGAR): busca o e-mail que o Endpoint 1 guardou
const emailCadastrado = pm.environment.get("email_dinamico");

// 🧱 PEÇA 2 (TESTAR STATUS): a API respondeu OK?
pm.test("Status code é 200 - Lista retornada", function () {
    pm.response.to.have.status(200);
});

// 🧱 PEÇA 3 (TESTAR VALOR): veio uma LISTA e ela não está vazia?
// "array" = lista em JavaScript. Analogia: uma fila de fichas de cadastro.
pm.test("A resposta é uma lista de usuários não vazia", function () {
    pm.expect(jsonData.data).to.be.an("array").and.not.be.empty;
});

// 🧱 PEÇA 3 (TESTAR VALOR): o usuário que criamos está na lista?
// .map() percorre a fila de fichas e separa SÓ os e-mails, numa lista nova.
// Depois conferimos se o nosso e-mail está entre eles.
pm.test("O usuário cadastrado aparece na lista", function () {
    const emails = jsonData.data.map(function (usuario) {
        return usuario.email;
    });
    pm.expect(emails).to.include(emailCadastrado);
});

// ============================================================
// ENDPOINT: [POST] Tentar Realizar Login com Senha Incorreta
// Objetivo: garantir que o sistema RECUSA um e-mail válido
// quando a senha está errada.
// ============================================================

// 🧱 PEÇA 2 (TESTAR STATUS): o acesso foi negado?
// 401 = "Unauthorized" (não autorizado)
pm.test("Status code deve ser 401 Unauthorized", function () {
    pm.response.to.have.status(401);
});

// 🧱 PEÇA 3 (TESTAR VALOR): a mensagem de erro é genérica?
// Boa prática de SEGURANÇA: a mensagem não diz se o erro foi no e-mail ou na senha.
// Se dissesse "senha errada", um invasor saberia que o e-mail existe.
pm.test("Mensagem de erro genérica (não revela se o e-mail existe)", function () {
    pm.expect(pm.response.text()).to.include("Invalid email or password.");
});

// 🧱 PEÇA 3 (SEGURANÇA): nenhum token pode ser entregue num login recusado
pm.test("Segurança: nenhum token é retornado", function () {
    pm.expect(pm.response.text()).to.not.include("token");
});

// ============================================================
// ENDPOINT: [POST] Tentar Realizar Login com E-mail Inexistente
// Objetivo: garantir que o sistema RECUSA um e-mail que
// não está cadastrado, sem revelar que ele não existe.
// ============================================================

// 🧱 PEÇA 2 (TESTAR STATUS): o acesso foi negado?
// 401 = "Unauthorized" (não autorizado)
pm.test("Status code deve ser 401 Unauthorized", function () {
    pm.response.to.have.status(401);
});

// 🧱 PEÇA 3 (TESTAR VALOR): a mensagem é a MESMA do teste de senha errada?
// Segurança: se a mensagem fosse diferente (ex.: "e-mail não encontrado"),
// um invasor poderia testar vários e-mails para descobrir quais têm conta.
// Isso se chama "enumeração de usuários".
pm.test("Mensagem de erro genérica (igual à de senha incorreta)", function () {
    pm.expect(pm.response.text()).to.include("Invalid email or password.");
});

// 🧱 PEÇA 3 (SEGURANÇA): nenhum token pode ser entregue num login recusado
pm.test("Segurança: nenhum token é retornado", function () {
    pm.expect(pm.response.text()).to.not.include("token");
});
